	    // 색상 정보 생성			
		const url = itemData.image_url || '';
	    //이미지 api 호출 미사용
   		//const mabibaseUrl = `${jumoney_url}${jumoney_key2[firstKey]}?colors=${getUrlColor(color)}" class="mabibase-img" onerror="this.src='./cute.png'` || './cute.png'; // Mabibase 이미지 URL
