	// 두 시간의 차이를 분 단위로 계산하는 함수
	function calculateTimeDifference(currentTime, resetTime) {
	    const diff = resetTime - currentTime; // 밀리초 단위 차이
	    return Math.max(Math.floor(diff / 1000 / 60), 0); // 분 단위로 변환 (0 이하 방지)
	}
	
	
